:root {
  --color-primary: #0A2463;
  --color-secondary: #3E92CC;
  --color-accent: #D8315B;
  --color-bg: #F4F7FB;
  --color-surface: #FFFFFF;
  --color-text-primary: #1B1B2F;
  --color-text-secondary: #5A6A7A;
  --color-border: #DDE3EC;

  --font-stack: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto,
                Helvetica, Arial, sans-serif;

  --radius-card: 12px;
  --shadow-card: 0 2px 8px rgba(10, 36, 99, 0.10);
  --shadow-card-hover: 0 6px 20px rgba(10, 36, 99, 0.18);

  --spacing-section: 48px;
  --spacing-card-gap: 24px;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-stack);
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.site-header {
  background-color: var(--color-primary);
  color: var(--color-surface);
  padding: 32px var(--spacing-card-gap);
  text-align: center;
}

.site-header__logo {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--color-surface);
}

.site-header__logo span {
  color: var(--color-secondary);
}

.site-header__tagline {
  font-size: 0.95rem;
  color: var(--color-secondary);
  margin-top: 4px;
  font-weight: 400;
}

.main-content {
  flex: 1;
  padding: var(--spacing-section) var(--spacing-card-gap);
  max-width: 1200px;
  width: 100%;
  margin: 0 auto;
}

.main-content__title {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 8px;
}

.main-content__subtitle {
  font-size: 0.95rem;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-section);
}

.cards-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-card-gap);
}

@media (min-width: 768px) {
  .cards-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .cards-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: box-shadow 0.25s ease, transform 0.25s ease;
}

.card:hover {
  box-shadow: var(--shadow-card-hover);
  transform: translateY(-3px);
}

.card__flag {
  font-size: 2.5rem;
  line-height: 1;
}

.card__country {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-secondary);
}

.card__greeting {
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--color-primary);
  line-height: 1.2;
}

.card__translation {
  font-size: 0.9rem;
  color: var(--color-text-secondary);
}

.card__pronunciation {
  font-size: 0.82rem;
  color: var(--color-accent);
  font-style: italic;
}

.site-footer {
  background-color: var(--color-primary);
  color: var(--color-surface);
  text-align: center;
  padding: 20px var(--spacing-card-gap);
  font-size: 0.85rem;
}

.site-footer a {
  color: var(--color-secondary);
  text-decoration: none;
}

.site-footer a:hover {
  text-decoration: underline;
}
